"""M5 measured reports distinguish common-feature window effects from frozen references."""
from pathlib import Path
import json
import pandas as pd
from .reporting import table

def write_comparison(directory):
    directory=Path(directory);meta=json.loads((directory/'metadata.json').read_text())
    c=pd.read_csv(directory/'comparison.csv');f=c[c.period.eq('examined_2024_2025')]
    if f.empty:f=c[c.period.eq('all_exploratory')]
    uniform=f[f.model.str.endswith('_uniform')|f.model.isin(['logistic','original_hgb','elo_extended','margin_elo_extended','elo_original','margin_elo_original','pregame_win_percentage'])]
    decay=pd.read_csv(directory/'decay_effects.csv');decay=decay[decay.period.eq('examined_2024_2025')]
    cols=['model','metric','estimate','difference','difference_low','difference_high','games']
    lines=['# M5 exploratory historical-training comparison','', 'Window selection uses development validation through 2021 only. Each common-feature window sees identical pregame state and evaluation games. W1 is the earliest *training-label* policy; it is not a reinitialization of priors/Elo. Original full-feature M2/M4 references use their original 2018-onward feature history and are exported separately.','', '## Development window ranking','',table(pd.read_csv(directory/'development_windows.csv')),'', '## Development decay ranking','',table(pd.read_csv(directory/'development_decay.csv')),'', 'Selected windows: `'+json.dumps(meta['selected_windows'])+'`; selected policies: `'+json.dumps(meta['selected_policies'])+'`. All candidates remain experimental.','', '## Uniform windows and references','',table(uniform[cols]),'', '## Recency differences from the same window uniform model','',table(decay[cols]) if len(decay) else 'No 2024–2025 decay subset in this protocol.','', 'Positive accuracy and negative Brier/log-loss differences favor the candidate. comparison.csv references the original M2 logistic; within_algorithm.csv references same-algorithm common-feature W1; decay_effects.csv references the identical-window uniform policy. These distinct references must not be conflated. All intervals are unadjusted exploratory paired season-week bootstrap intervals. An interval excluding zero after many comparisons is not independent confirmation.','', '## Source and calibration limits','',meta['kickoff_limits'],'', '1999–2000 PBP has some missing game coverage. Source and pregame feature completeness are reported separately; missing values remain missing until training-only preprocessing/native handling. EPA is a contemporary nflverse retrospective estimate and original source vintages are not reconstructed. Sigmoid/eligible isotonic variants are fit only on the intervening calibration season for the development-selected policy, never using evaluation outcomes. The first calibration year was also used for development; subsequent evaluation is separate but not a new untouched historical test.']
    (directory/'MODEL_COMPARISON.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')

def engineering_report(run,root):
    run=Path(run);root=Path(root);meta=json.loads((run/'metadata.json').read_text())
    qa=root/'docs/m5/VERIFICATION.json';verification=json.loads(qa.read_text()) if qa.exists() else {'status':'Verification evidence pending; report generation is not test execution.'}
    source_path=root/'reports/history_audit/source_audit.csv'
    source=pd.read_csv(source_path) if source_path.exists() else pd.DataFrame()
    c=pd.read_csv(run/'comparison.csv');f=c[c.period.eq('examined_2024_2025')]
    summary=f[f.model.str.endswith('_uniform')|f.model.isin(['logistic','original_hgb','elo_original','elo_extended','margin_elo_original','margin_elo_extended','pregame_win_percentage'])].pivot(index='model',columns='metric',values='estimate').reset_index()
    uniforms=f[(f.model.str.endswith('_uniform')|f.model.isin(['logistic','original_hgb','elo_original','elo_extended','margin_elo_original','margin_elo_extended','pregame_win_percentage']))&f.metric.eq('brier')]
    within=pd.read_csv(run/'within_algorithm.csv');within=within[within.period.eq('examined_2024_2025') & within.metric.eq('brier') & within.model.str.endswith('_uniform')]
    warmup=pd.read_csv(run/'elo_warmup.csv') if (run/'elo_warmup.csv').exists() else pd.DataFrame()
    if len(warmup):warmup=warmup[warmup.period.eq('examined_2024_2025')&warmup.metric.eq('brier')]
    original_boost=pd.read_csv(run/'vs_original_boosting.csv') if (run/'vs_original_boosting.csv').exists() else pd.DataFrame()
    if len(original_boost):original_boost=original_boost[original_boost.period.eq('examined_2024_2025')&original_boost.metric.eq('brier')&original_boost.model.str.endswith('_uniform')]
    training=pd.read_csv(run/'training_metadata.csv');trials=pd.read_csv(run/'development_trials.csv')
    features=pd.read_csv(run/'feature_completeness.csv') if (run/'feature_completeness.csv').exists() else pd.DataFrame()
    answers=[]
    for algorithm,label in [('logistic','Logistic'),('hgb','Shallow boosting')]:
        candidates=f[f.metric.eq('brier')&f.model.str.startswith(algorithm+'_W')&f.model.str.endswith('_uniform')]
        if len(candidates):
            first=candidates[candidates.model.eq(algorithm+'_W1_uniform')].iloc[0]
            best=candidates.sort_values('estimate').iloc[0]
            maximum=candidates[candidates.model.eq(algorithm+'_W4_uniform')].iloc[0]
            answers.append(f"{label}: W1-common Brier {first.estimate:.6f}; best observed uniform window {best.model} at {best.estimate:.6f}; maximum-history W4 {maximum.estimate:.6f}. The observed-best window is descriptive, not a new choice using evaluation outcomes.")
    answers.append('Development-selected policies: '+json.dumps(meta['selected_policies'])+'. Uniform winners imply that decay was not selected on development data; later isolated decay gains do not reverse that decision. A universal optimal history length or half-life is not established.')
    lines=['# M5 engineering report','', '## Scope, baseline and authorization','', 'M5 adds 1999–2017 source ingestion, season audits, compact historical pregame caches, staged window selection and exponential sample weighting for the existing logistic and fixed shallow HGB estimators. Development proceeded at risk while native Windows M4 acceptance remains pending. The actual starting suite passed 74 tests on Linux/Python 3.12. The champion, existing registry, forecasts, Elo histories and reports are preserved; see docs/m5/BASELINE.json and verification evidence below. No M5 candidate was activated. M6 was not started.','', '## Source coverage and completeness','',table(source),'', 'Historical ingestion is season-by-season, resumable and manifest-atomic. Required columns, data types, null rates, game/PBP counts, retrieval time, source hashes, processing version, incomplete games and metric distributions are recorded in source_audit.json and each new season manifest. Earlier raw seasons are not retained together in process memory. Unchanged verified caches are reused; failed downloads cannot publish a half season. Each raw file is independently checked on reads.','', '1999 has no kickoff clock in schedules, start_time or time_of_day. It uses a clearly labeled local-day LOWER BOUND for feature cutoff, with result eligibility no earlier than next day 08:00 Eastern (latest possible local-day kickoff plus eight hours). This is conservative date-interval processing, not a reconstructed actual kickoff. Other inspected seasons supply scheduled clocks. Prior-game rest is not identifiable for date-only data, so **rest is excluded from every common-feature window**. Neutral status is missing if source venue is unknown. No missing football statistics are fabricated.','', 'Source metric completeness is distinct from complete pregame inputs. Missing play-by-play games in 1999/2000 and initialization-season priors remain explicit; training-only imputation or native partial-missing handling is permitted and reported, not disguised as source coverage. Modern 2026 is incomplete/ongoing and is not scored as a prospective experiment.','',table(features),'', '## Statistical compatibility and era effects','', 'The same eligible scrimmage policy is used across eras: run/pass including sacks, excluding kneels/spikes/administrative/special teams and missing EPA. Offensive/defensive EPA and success are from the possession/opposing-team perspective; game means receive equal weights. Success is EPA>0. Turnovers are interceptions plus lost fumbles on eligible plays. Passing production is net eligible pass-play yards (including sacks), not official gross passing yards; rushing production uses eligible run-play yards. Descriptive production fields are audited, not added to model feature sets.','', 'Actual historical schemas include the required EPA, yardage, turnover and kneel/spike fields. Matching column definitions does not establish identical statistical distributions or source-model calibration. Per-season means, medians, standard deviations and null rates are exported. Modern historical EPA may itself use a retrospectively estimated expected-points model; rolling feature cutoffs do not reconstruct its original publication/model vintage.','', 'Relevant era changes include passing/contact/protection enforcement, evolving offensive strategy, kickoff placement/touchback and dynamic-kickoff changes, overtime formats and the 17-game transition in 2021. Houston expansion and Seattle division realignment also change league structure. No rule-era or division indicators were automatically added. Distribution drift is descriptive, not a causal rule-change estimate. Abbreviations OAK→LV, SD→LAC, STL/LAR→LA and other existing aliases preserve franchise identity. Houston has no pre-2002 team prior and falls back to the prior-season league mean. The 2001 postponements are ordered by actual recorded dates, not nominal week alone.','', '## Feature reconstruction and original references','', meta['feature_history'],'', 'Each compact season cache uses the current and previous season (all needed statistical priors), strict earlier-result availability and four-game prior shrinkage. Source/code hashes invalidate only affected caches; longer Elo is replayed over the compact schedule sequence separately. The four-game prior and 50% offseason league regression remain fixed, not tuned against 2024–2025. season_phase.csv reports weeks 1–3 versus later results to review early-prior behavior without selecting a new prior on these outcomes; four games is not claimed optimal across eras. Initialization lacks 1998 data and is explicitly labeled; early-season missing values are not replaced by future source values.','', 'Original M2 logistic and M4 shallow-HGB references are reconstructed from the unchanged 2018–2026 cache through their original endpoints, preserving mature-history differences as a separate reference. Main window comparisons use the same common features and 1999-onward prior/Elo history for ALL window policies. Therefore W1-common may differ from the exact original full-feature benchmark; within_algorithm.csv is the fair window-effect reference. Rest removal and richer initialization must not be misattributed to extra training labels.','', '## Staged window and recency selection','', 'W1=2018, W2=2013, W3=2008, W4=1999 are earliest eligible label-season policies. Development folds validate 2019/2020/2021 after training endpoints 2018/2019/2020. Uniform windows are ranked per algorithm by equal-season mean Brier then log loss. The top two windows per algorithm receive predefined 3/5/8-year decay; one primary policy is selected using those same development years. Later-year comparisons never feed back into selection. Shallow HGB parameters stay fixed at the M4-selected values; there is no tree/feature/prior retuning.','',table(pd.read_csv(run/'development_windows.csv')),'',table(pd.read_csv(run/'development_decay.csv')),'', 'Selected experimental policies: `'+json.dumps(meta['selected_policies'])+'`. Configuration counts: `'+json.dumps(meta['configuration_counts'])+'`.','', 'Weights are 0.5**(age_years/half_life), age at each specific historical fit cutoff, never today. One year=365.25 days; weights normalize to mean one, preserving total likelihood scale relative to fixed L2. Effective sample size is (sum w)^2/sum(w^2). No records are duplicated. Logistic uses training-only unweighted mean imputation, weighted StandardScaler and weighted logistic loss; HGB receives sample_weight directly. All-empty training columns retain the M4 exclusions/fallback.','', '## Measured probability-quality comparison, examined 2024–2025','',table(summary),'',table(uniforms[['model','estimate','difference','difference_low','difference_high','games']]),'', 'Differences above reference the exact original logistic. Complete accuracy, Brier, log loss and sample sizes appear in MODEL_COMPARISON.md and comparison.csv. within_algorithm.csv directly isolates each common-feature window against same-algorithm W1, while decay_effects.csv isolates each half-life against its same-window uniform model. Read all references carefully; feature-history/feature-set differences from the original benchmark are separate from training-window effects.','', '## Direct window effects and four experiment questions','', '\n\n'.join(answers),'',table(within[['model','estimate','difference','difference_low','difference_high','games']]),'', '1. **Logistic history expansion:** compare same-feature uniform policies above. More data is not automatically better; the development-selected window may differ from the best later point estimate, and no later-year choice replaces it.','2. **Boosting history expansion:** compare the same-feature W1 and expanded windows, then separately the original M4 full-feature reference below. These isolate different questions; one comparison cannot substitute for the other.','3. **Optimal window:** the selected 2008-or-other policy is a development choice recorded above, not a proven universal optimum. Maximum 1999 coverage need not win.','4. **Recency:** uniform and 3/5/8-year policies are compared within selected windows. A later exploratory gain is not selection authority; uniform may remain the development winner. No generally reliable superiority claim follows from a single interval.','',table(original_boost[['model','estimate','difference','difference_low','difference_high','games']]) if len(original_boost) else 'No original-booster comparison for this period.','', '## Elo warm-up, calibration and uncertainty','', 'Standard and margin Elo compare 1999 versus 2018 initialization separately, using the same evaluation games and fixed parameters. Main HGB windows share the extended Elo stream, so their window differences do not confound separate rating warm-up. No early initialized Elo is represented as mature historical evidence.','', table(warmup[['model','estimate','difference','difference_low','difference_high','games']]) if len(warmup) else 'No warm-up comparison for this period.','', 'Reliability diagrams, identifiable calibration intercept/slope, probability and confidence buckets are exported for every comparison. Only development-selected policies receive sigmoid/adequately supported isotonic variants, fit in separate intervening years. The first calibration year overlaps development (2021), which limits model-selection independence; evaluation remains strictly later. No calibrated variant is automatically selected for production.','', 'Paired season-week percentile bootstrap intervals reuse M2–M4 methods on identical games. Few seasons, repeated teams, interweek dependence and many exploratory comparisons remain limitations. One interval excluding zero is not by itself a superiority claim. The repeatedly examined 2024–2025 seasons are not independent confirmation. Existing 2026 official forecasts are neither rewritten nor retroactively issued by M5.','', '## Storage and runtime','', f"Development fits recorded: {len(trials)}; total measured fit seconds {trials.runtime_seconds.sum():.3f}. Forward uncalibrated fits: {len(training)}; total measured fit seconds {training.runtime_seconds.sum():.3f}. CPU threads capped at {meta['protocol']['cpu_threads']}. These figures exclude initial downloads/features and vary by machine.",'', 'Training uses compact pregame matrices, never raw PBP per candidate. Raw ingestion disables nflreadpy memory accumulation and processes one season at a time; source hashes and immutable season generations provide local reuse. Audit loading is also season-bounded. Compact feature reconstruction prunes statistical context to current/prior season and caches each output. Native Windows peak-memory/runtime behavior remains unmeasured; Linux evidence is included below. Recorded process peak RSS: '+str(meta.get('linux_or_macos_peak_rss_bytes'))+' bytes (includes feature/audit/model work in that process; not Windows RAM certification).','', '## Registry and preservation','', 'The additive M4 registry records window start/end policy, weighting half-life/cutoff/normalization/effective size, feature schema, fixed algorithm parameters, calibration, dataset fingerprint, evaluation and experimental designation. M5 artifacts carry activation_blocked and registry activation explicitly refuses them even with an approval JSON. Existing M4 activation/rollback support remains intact; no destructive database changes occur.','', '## Tests and combined Windows acceptance','', '```json\n'+json.dumps(verification,indent=2)+'\n```','', 'No genuine Windows environment is available in this task. Combined M4/M5 Windows-native acceptance is **not passed**. A PowerShell checklist/script covers installation, imports, CLI, source/audit/cache reuse, both algorithms, weighted experiments, calibration, registry, dashboard, upcoming games and preservation. Linux checks cannot certify Windows RAM/runtime behavior or native dependencies.','', '## Launch and outstanding limits','', 'With the virtual environment active: `python -m nfl_predictor.cli update-history --start 1999 --end 2017`; `python -m nfl_predictor.cli audit-history`; `python -m nfl_predictor.cli compare-history`; `python -m nfl_predictor.cli report-m5`; `python -m streamlit run app.py`. Historical Training Analysis appears within Model Analysis. Training never runs during page rendering. Default M1–M4 commands retain the original modern history unless expansion is explicitly requested.','', 'Measured run: `'+str(run)+'`. Source audits and all generated windows/weights/model diagnostics remain separate from the official forecast database. Downloaded raw datasets, SQLite and model binaries are ignored by Git; local environment caches contain the downloaded seasons. Missing dates, corrected/vintage EPA, incomplete early PBP and exact historical publication timing remain material limits.','', '## Promotion recommendation and M6 priorities','', 'Keep the official M2 champion. Historical findings are exploratory and cannot supersede at-risk Windows acceptance or future explicit approval. Complete combined native Windows acceptance, collect independent prospective outcomes, improve early PBP/time evidence and verify era stability before considering promotion. M6 was not started.']
    path=root/'M5_ENGINEERING_REPORT.md';path.write_text('\n'.join(lines)+'\n',encoding='utf-8');return path
